create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,role text not null default 'user' check(role in ('user','admin')),credits integer not null default 0,free_trial_used boolean not null default false,device_hash text,ip_hash text,created_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,status text not null default 'queued',credits_used integer not null default 0,source_name text,source_path text,target_language text,output_ratio text,instruction text,created_at timestamptz not null default now());
create table if not exists public.credit_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,plan_name text not null,credits integer not null,price numeric(12,2) not null,status text not null default 'pending',created_at timestamptz not null default now(),approved_at timestamptz);
create table if not exists public.credit_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,amount integer not null,reason text,project_id uuid references public.projects(id) on delete set null,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.spend_credits(p_user_id uuid,p_amount integer,p_reason text,p_project_id uuid default null) returns void language plpgsql security definer set search_path=public as $$ declare c integer; begin if auth.uid()<>p_user_id and not public.is_admin() then raise exception 'not allowed'; end if; select credits into c from profiles where id=p_user_id for update; if c is null or c<p_amount then raise exception 'insufficient credits'; end if; update profiles set credits=credits-p_amount where id=p_user_id; insert into credit_ledger(user_id,amount,reason,project_id) values(p_user_id,-p_amount,p_reason,p_project_id); end $$;
create or replace function public.approve_credit_request(p_request_id uuid,p_user_id uuid,p_amount integer) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'admin only'; end if; update credit_requests set status='approved',approved_at=now() where id=p_request_id and status='pending'; update profiles set credits=credits+p_amount where id=p_user_id; insert into credit_ledger(user_id,amount,reason) values(p_user_id,p_amount,'Approved credit request'); end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email) on conflict do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.credit_requests enable row level security; alter table public.credit_ledger enable row level security;
drop policy if exists profiles_self on public.profiles; create policy profiles_self on public.profiles for select using(id=auth.uid() or public.is_admin());
drop policy if exists projects_self on public.projects; create policy projects_self on public.projects for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
drop policy if exists requests_self on public.credit_requests; create policy requests_self on public.credit_requests for insert with check(user_id=auth.uid()); create policy requests_read on public.credit_requests for select using(user_id=auth.uid() or public.is_admin());
drop policy if exists ledger_self on public.credit_ledger; create policy ledger_self on public.credit_ledger for select using(user_id=auth.uid() or public.is_admin());
insert into storage.buckets(id,name,public) values('videos','videos',false) on conflict(id) do nothing;
drop policy if exists video_owner on storage.objects; create policy video_owner on storage.objects for all to authenticated using(bucket_id='videos' and (split_part(name,'/',1)=auth.uid()::text or public.is_admin())) with check(bucket_id='videos' and (split_part(name,'/',1)=auth.uid()::text or public.is_admin()));
